# Let me convert to numpy and identify shapes
grid_np = np.array(grid)

def find_connected_components(grid, color):
    """Find positions of a given color that form connected components."""
    positions = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                positions.append((r, c))
    return positions

# Find all shapes by color
colors_to_find = [2, 3, 4, 5, 6, 8]
for color in colors_to_find:
    positions = find_connected_components(grid, color)
    if positions:
        print(f"Color {color} has {len(positions)} cells at positions: {positions}")

# Analyze each shape
print("\n--- Shape Analysis ---")
color_flows = {}
for color in colors_to_find:
    positions = find_connected_components(grid, color)
    if positions:
        # Check if they form a connected shape
        cells = sorted(positions)
        if len(cells) <= 3:
            color_flows[color] = {'horizontal': sum(c[1] - cells[0][1] for c in cells[1:] if cells[0][0] == cells[1][0]) == 0}
        else:
            color_flows[color] = {'spread': max(c[0] for c in cells) - min(c[0] for c in cells), 
                                   'wide': max(c[1] for c in cells) - min(c[1] for c in cells)}

print(f"Color flow analysis: {color_flows}")

